	//     {
	//         "e": "24hTicker",
	//         "E": 1706498923556,
	//         "s": "BTC-USDT",
	//         "p": "346.4",
	//         "P": "0.82",
	//         "c": "42432.5",
	//         "L": "0.0529",
	//         "h": "42855.4",
	//         "l": "41578.3",
	//         "v": "64310.9754",
	//         "q": "2728360284.15",
	//         "o": "42086.1",
	//         "O": 1706498922655,
	//         "C": 1706498883023,
	//         "A": "42437.8",
	//         "a": "1.4160",
	//         "B": "42437.1",
	//         "b": "2.5747"
	//     }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	isInverse := ccxt.GetArg(optionalArgs, 1, nil)
	_ = isInverse
	var timestamp *int64 = this.SafeInteger(message, "C")
	var marketId *string = this.SafeString(message, "s")
